"""
Workflow data transformation module for processing step outputs.
"""
import ast
from typing import Any, Dict


class SafeExpressionError(Exception):
    """Raised when an unsafe expression is detected."""
    pass


class SafeExpressionEvaluator(ast.NodeVisitor):
    """
    AST visitor that validates expressions are safe before evaluation.
    Only allows: dict literals, arithmetic, comparison, logical operators,
    subscript access, and attribute access (with restrictions).
    """

    SAFE_BUILTIN_FUNCS = frozenset({'len', 'str', 'int', 'float', 'bool', 'list', 'dict', 'tuple', 'abs', 'min', 'max', 'sum', 'round'})
    FORBIDDEN_ATTRIBUTES = frozenset({'__class__', '__bases__', '__mro__', '__subclasses__', '__code__', '__globals__', '__builtins__', '__import__', '__dict__', '__module__', '__reduce__', '__reduce_ex__', '__getattribute__', '__setattr__', '__delattr__'})

    def __init__(self, allowed_names: frozenset):
        self.allowed_names = allowed_names

    def visit(self, node: ast.AST) -> None:
        """Visit a node and validate it's safe."""
        method = 'visit_' + node.__class__.__name__
        visitor = getattr(self, method, self.generic_visit)
        return visitor(node)

    def generic_visit(self, node: ast.AST) -> None:
        """Reject any node type not explicitly allowed."""
        raise SafeExpressionError(f"Unsafe expression: {node.__class__.__name__} is not allowed")

    def visit_Expression(self, node: ast.Expression) -> None:
        self.visit(node.body)

    def visit_Dict(self, node: ast.Dict) -> None:
        for key in node.keys:
            if key is not None:
                self.visit(key)
        for value in node.values:
            self.visit(value)

    def visit_List(self, node: ast.List) -> None:
        for elt in node.elts:
            self.visit(elt)

    def visit_Tuple(self, node: ast.Tuple) -> None:
        for elt in node.elts:
            self.visit(elt)

    def visit_Constant(self, node: ast.Constant) -> None:
        # Allow string, number, boolean, None constants
        if not isinstance(node.value, (str, int, float, bool, type(None))):
            raise SafeExpressionError(f"Unsafe constant type: {type(node.value)}")

    def visit_Name(self, node: ast.Name) -> None:
        if node.id not in self.allowed_names and node.id not in self.SAFE_BUILTIN_FUNCS:
            raise SafeExpressionError(f"Unsafe name: '{node.id}' is not allowed")

    def visit_Subscript(self, node: ast.Subscript) -> None:
        self.visit(node.value)
        self.visit(node.slice)

    def visit_Index(self, node: ast.Index) -> None:
        # For Python 3.8 compatibility
        self.visit(node.value)

    def visit_Slice(self, node: ast.Slice) -> None:
        if node.lower:
            self.visit(node.lower)
        if node.upper:
            self.visit(node.upper)
        if node.step:
            self.visit(node.step)

    def visit_Attribute(self, node: ast.Attribute) -> None:
        if node.attr in self.FORBIDDEN_ATTRIBUTES or node.attr.startswith('_'):
            raise SafeExpressionError(f"Unsafe attribute access: '{node.attr}' is not allowed")
        self.visit(node.value)

    def visit_BinOp(self, node: ast.BinOp) -> None:
        self.visit(node.left)
        self.visit(node.right)

    def visit_UnaryOp(self, node: ast.UnaryOp) -> None:
        self.visit(node.operand)

    def visit_Compare(self, node: ast.Compare) -> None:
        self.visit(node.left)
        for comparator in node.comparators:
            self.visit(comparator)

    def visit_BoolOp(self, node: ast.BoolOp) -> None:
        for value in node.values:
            self.visit(value)

    def visit_IfExp(self, node: ast.IfExp) -> None:
        self.visit(node.test)
        self.visit(node.body)
        self.visit(node.orelse)

    def visit_Call(self, node: ast.Call) -> None:
        # Only allow calls to safe built-in functions
        if isinstance(node.func, ast.Name):
            if node.func.id not in self.SAFE_BUILTIN_FUNCS:
                raise SafeExpressionError(f"Unsafe function call: '{node.func.id}' is not allowed")
        else:
            raise SafeExpressionError("Only direct calls to safe built-in functions are allowed")

        for arg in node.args:
            self.visit(arg)
        for keyword in node.keywords:
            self.visit(keyword.value)

    def visit_ListComp(self, node: ast.ListComp) -> None:
        self.visit(node.elt)
        for generator in node.generators:
            self.visit_comprehension(generator)

    def visit_DictComp(self, node: ast.DictComp) -> None:
        self.visit(node.key)
        self.visit(node.value)
        for generator in node.generators:
            self.visit_comprehension(generator)

    def visit_comprehension(self, node: ast.comprehension) -> None:
        self.visit(node.iter)
        # Allow the loop variable
        if isinstance(node.target, ast.Name):
            pass  # Loop variables are OK
        self.visit(node.target)
        for if_clause in node.ifs:
            self.visit(if_clause)


def validate_expression(expr: str, allowed_names: frozenset) -> ast.Expression:
    """
    Parse and validate that an expression is safe.

    Args:
        expr: The expression string to validate
        allowed_names: Set of allowed variable names

    Returns:
        The parsed AST if safe

    Raises:
        SafeExpressionError: If the expression is unsafe
        SyntaxError: If the expression is not valid Python
    """
    try:
        tree = ast.parse(expr, mode='eval')
    except SyntaxError as e:
        raise SafeExpressionError(f"Invalid expression syntax: {e}")

    validator = SafeExpressionEvaluator(allowed_names)
    validator.visit(tree)

    return tree


def transform_step_data(transform_map_expr: str, input_data: dict) -> dict:
    """
    Transforms input data using a provided expression string.

    Args:
        transform_map_expr: A string representing a Python dictionary literal
                           that defines how to map input fields to output fields.
                           Can reference input_data variable.
        input_data: Dictionary containing the input data from a previous step.

    Returns:
        A new dictionary with transformed data according to the expression.

    Raises:
        SafeExpressionError: If the expression contains unsafe operations
        TypeError: If the result is not a dictionary
    """
    if not isinstance(input_data, dict):
        raise TypeError("input_data must be a dictionary")

    if not isinstance(transform_map_expr, str):
        raise TypeError("transform_map_expr must be a string")

    # Define allowed names - only input_data as specified
    allowed_names = frozenset({'input_data'})

    # Validate the expression is safe
    validate_expression(transform_map_expr, allowed_names)

    # Create a restricted namespace for evaluation
    safe_builtins = {
        'len': len,
        'str': str,
        'int': int,
        'float': float,
        'bool': bool,
        'list': list,
        'dict': dict,
        'tuple': tuple,
        'abs': abs,
        'min': min,
        'max': max,
        'sum': sum,
        'round': round,
        'True': True,
        'False': False,
        'None': None,
    }

    # Create evaluation namespace with only the allowed variables
    eval_namespace = {
        '__builtins__': safe_builtins,
        'input_data': input_data,
    }

    # Execute the transformation expression
    result = eval(transform_map_expr, eval_namespace, {})

    if not isinstance(result, dict):
        raise TypeError(f"Transform expression must return a dictionary, got {type(result).__name__}")

    return result

"""
Workflow data transformation module for processing step outputs.
"""
import ast
import operator


# Safe operators mapping
SAFE_OPERATORS = {
    ast.Add: operator.add,
    ast.Sub: operator.sub,
    ast.Mult: operator.mul,
    ast.Div: operator.truediv,
    ast.FloorDiv: operator.floordiv,
    ast.Mod: operator.mod,
    ast.Pow: operator.pow,
    ast.USub: operator.neg,
    ast.UAdd: operator.pos,
    ast.Eq: operator.eq,
    ast.NotEq: operator.ne,
    ast.Lt: operator.lt,
    ast.LtE: operator.le,
    ast.Gt: operator.gt,
    ast.GtE: operator.ge,
    ast.And: lambda a, b: a and b,
    ast.Or: lambda a, b: a or b,
    ast.Not: operator.not_,
    ast.In: lambda a, b: a in b,
    ast.NotIn: lambda a, b: a not in b,
}


class SafeEvaluator(ast.NodeVisitor):
    """
    A safe expression evaluator that only allows specific operations.
    """

    def __init__(self, input_data: dict):
        self.input_data = input_data

    def evaluate(self, expr: str) -> dict:
        """Parse and evaluate the expression safely."""
        try:
            tree = ast.parse(expr, mode='eval')
        except SyntaxError as e:
            raise ValueError(f"Invalid expression syntax: {e}")

        result = self.visit(tree.body)

        if not isinstance(result, dict):
            raise ValueError("Expression must evaluate to a dictionary")

        return result

    def visit_Dict(self, node):
        """Handle dictionary literals."""
        keys = [self.visit(k) for k in node.keys]
        values = [self.visit(v) for v in node.values]
        return dict(zip(keys, values))

    def visit_List(self, node):
        """Handle list literals."""
        return [self.visit(elem) for elem in node.elts]

    def visit_Tuple(self, node):
        """Handle tuple literals."""
        return tuple(self.visit(elem) for elem in node.elts)

    def visit_Constant(self, node):
        """Handle constant values (strings, numbers, None, True, False)."""
        return node.value

    def visit_Num(self, node):
        """Handle numeric literals (Python 3.7 compatibility)."""
        return node.n

    def visit_Str(self, node):
        """Handle string literals (Python 3.7 compatibility)."""
        return node.s

    def visit_NameConstant(self, node):
        """Handle True, False, None (Python 3.7 compatibility)."""
        return node.value

    def visit_Name(self, node):
        """Handle variable names - only allow 'input_data'."""
        if node.id == 'input_data':
            return self.input_data
        elif node.id in ('True', 'False', 'None'):
            return {'True': True, 'False': False, 'None': None}[node.id]
        else:
            raise ValueError(f"Access to variable '{node.id}' is not allowed. Use 'input_data' to reference input.")

    def visit_Subscript(self, node):
        """Handle subscript access like input_data['key'] or input_data[0]."""
        value = self.visit(node.value)
        slice_val = self.visit(node.slice)
        return value[slice_val]

    def visit_Index(self, node):
        """Handle index (Python 3.8 compatibility)."""
        return self.visit(node.value)

    def visit_Attribute(self, node):
        """Handle attribute access like input_data.get."""
        value = self.visit(node.value)
        attr = node.attr

        # Only allow safe methods on dictionaries and lists
        safe_dict_methods = {'get', 'keys', 'values', 'items'}
        safe_list_methods = {'index', 'count'}
        safe_str_methods = {'lower', 'upper', 'strip', 'split', 'join', 'replace', 'startswith', 'endswith'}

        if isinstance(value, dict) and attr in safe_dict_methods:
            return getattr(value, attr)
        elif isinstance(value, list) and attr in safe_list_methods:
            return getattr(value, attr)
        elif isinstance(value, str) and attr in safe_str_methods:
            return getattr(value, attr)
        else:
            raise ValueError(f"Attribute access '.{attr}' is not allowed")

    def visit_Call(self, node):
        """Handle function calls - only allow safe built-in functions and methods."""
        func = self.visit(node.func)
        args = [self.visit(arg) for arg in node.args]
        kwargs = {kw.arg: self.visit(kw.value) for kw in node.keywords}

        # Check if it's a callable (method from allowed attributes)
        if callable(func):
            return func(*args, **kwargs)

        raise ValueError("Function calls are not allowed except for safe methods")

    def visit_BinOp(self, node):
        """Handle binary operations."""
        left = self.visit(node.left)
        right = self.visit(node.right)
        op_type = type(node.op)

        if op_type not in SAFE_OPERATORS:
            raise ValueError(f"Operator {op_type.__name__} is not allowed")

        return SAFE_OPERATORS[op_type](left, right)

    def visit_UnaryOp(self, node):
        """Handle unary operations."""
        operand = self.visit(node.operand)
        op_type = type(node.op)

        if op_type not in SAFE_OPERATORS:
            raise ValueError(f"Unary operator {op_type.__name__} is not allowed")

        return SAFE_OPERATORS[op_type](operand)

    def visit_Compare(self, node):
        """Handle comparison operations."""
        left = self.visit(node.left)

        for op, comparator in zip(node.ops, node.comparators):
            right = self.visit(comparator)
            op_type = type(op)

            if op_type not in SAFE_OPERATORS:
                raise ValueError(f"Comparison operator {op_type.__name__} is not allowed")

            if not SAFE_OPERATORS[op_type](left, right):
                return False
            left = right

        return True

    def visit_BoolOp(self, node):
        """Handle boolean operations (and, or)."""
        op_type = type(node.op)

        if op_type not in SAFE_OPERATORS:
            raise ValueError(f"Boolean operator {op_type.__name__} is not allowed")

        values = [self.visit(v) for v in node.values]

        if op_type == ast.And:
            result = values[0]
            for v in values[1:]:
                result = result and v
            return result
        else:  # ast.Or
            result = values[0]
            for v in values[1:]:
                result = result or v
            return result

    def visit_IfExp(self, node):
        """Handle ternary expressions (a if condition else b)."""
        test = self.visit(node.test)
        if test:
            return self.visit(node.body)
        else:
            return self.visit(node.orelse)

    def generic_visit(self, node):
        """Reject any node types not explicitly handled."""
        raise ValueError(f"Expression contains disallowed construct: {type(node).__name__}")


def transform_step_data(transform_map_expr: str, input_data: dict) -> dict:
    """
    Transforms input data using a provided expression string.

    Args:
        transform_map_expr: A string representing a Python dictionary literal
                           that defines how to map input fields to output fields.
                           Can reference input data using 'input_data' variable.
        input_data: Dictionary containing the input data from a previous step.

    Returns:
        A new dictionary with transformed data according to the expression.

    Raises:
        ValueError: If the expression contains disallowed constructs or syntax errors.
    """
    if not isinstance(input_data, dict):
        raise TypeError("input_data must be a dictionary")

    if not isinstance(transform_map_expr, str):
        raise TypeError("transform_map_expr must be a string")

    evaluator = SafeEvaluator(input_data)
    return evaluator.evaluate(transform_map_expr)

"""
Workflow data transformation module for processing step outputs.
"""

import ast
import operator


# Safe operators mapping
SAFE_OPERATORS = {
    ast.Add: operator.add,
    ast.Sub: operator.sub,
    ast.Mult: operator.mul,
    ast.Div: operator.truediv,
    ast.FloorDiv: operator.floordiv,
    ast.Mod: operator.mod,
    ast.Pow: operator.pow,
    ast.USub: operator.neg,
    ast.UAdd: operator.pos,
    ast.Eq: operator.eq,
    ast.NotEq: operator.ne,
    ast.Lt: operator.lt,
    ast.LtE: operator.le,
    ast.Gt: operator.gt,
    ast.GtE: operator.ge,
    ast.And: lambda a, b: a and b,
    ast.Or: lambda a, b: a or b,
    ast.Not: operator.not_,
    ast.In: lambda a, b: a in b,
    ast.NotIn: lambda a, b: a not in b,
}


class SafeExpressionEvaluator(ast.NodeVisitor):
    """
    A safe expression evaluator that only allows specific operations.
    """

    def __init__(self, variables: dict):
        self.variables = variables

    def evaluate(self, expr: str):
        """Parse and evaluate an expression safely."""
        try:
            tree = ast.parse(expr, mode='eval')
        except SyntaxError as e:
            raise ValueError(f"Invalid expression syntax: {e}")

        return self.visit(tree.body)

    def visit_Expression(self, node):
        return self.visit(node.body)

    def visit_Constant(self, node):
        """Handle constant values (numbers, strings, None, True, False)."""
        return node.value

    # Python 3.7 compatibility
    def visit_Num(self, node):
        return node.n

    def visit_Str(self, node):
        return node.s

    def visit_NameConstant(self, node):
        return node.value

    def visit_Name(self, node):
        """Handle variable references."""
        if node.id in self.variables:
            return self.variables[node.id]
        raise ValueError(f"Undefined variable: {node.id}")

    def visit_Dict(self, node):
        """Handle dictionary literals."""
        keys = [self.visit(k) for k in node.keys]
        values = [self.visit(v) for v in node.values]
        return dict(zip(keys, values))

    def visit_List(self, node):
        """Handle list literals."""
        return [self.visit(elem) for elem in node.elts]

    def visit_Tuple(self, node):
        """Handle tuple literals."""
        return tuple(self.visit(elem) for elem in node.elts)

    def visit_BinOp(self, node):
        """Handle binary operations."""
        op_type = type(node.op)
        if op_type not in SAFE_OPERATORS:
            raise ValueError(f"Unsupported operator: {op_type.__name__}")

        left = self.visit(node.left)
        right = self.visit(node.right)
        return SAFE_OPERATORS[op_type](left, right)

    def visit_UnaryOp(self, node):
        """Handle unary operations."""
        op_type = type(node.op)
        if op_type not in SAFE_OPERATORS:
            raise ValueError(f"Unsupported unary operator: {op_type.__name__}")

        operand = self.visit(node.operand)
        return SAFE_OPERATORS[op_type](operand)

    def visit_Compare(self, node):
        """Handle comparison operations."""
        left = self.visit(node.left)

        for op, comparator in zip(node.ops, node.comparators):
            op_type = type(op)
            if op_type not in SAFE_OPERATORS:
                raise ValueError(f"Unsupported comparison operator: {op_type.__name__}")

            right = self.visit(comparator)
            if not SAFE_OPERATORS[op_type](left, right):
                return False
            left = right

        return True

    def visit_BoolOp(self, node):
        """Handle boolean operations (and, or)."""
        op_type = type(node.op)
        if op_type not in SAFE_OPERATORS:
            raise ValueError(f"Unsupported boolean operator: {op_type.__name__}")

        values = [self.visit(v) for v in node.values]

        if op_type == ast.And:
            result = True
            for v in values:
                result = result and v
                if not result:
                    return result
            return result
        else:  # Or
            result = False
            for v in values:
                result = result or v
                if result:
                    return result
            return result

    def visit_Subscript(self, node):
        """Handle subscript operations (e.g., input_data['key'])."""
        value = self.visit(node.value)

        # Handle different slice types
        if isinstance(node.slice, ast.Index):
            # Python 3.8 and earlier
            index = self.visit(node.slice.value)
        else:
            # Python 3.9+
            index = self.visit(node.slice)

        return value[index]

    def visit_Attribute(self, node):
        """Handle attribute access (e.g., input_data.get)."""
        value = self.visit(node.value)
        attr = node.attr

        # Only allow safe attribute access on dicts and lists
        safe_dict_attrs = {'get', 'keys', 'values', 'items'}
        safe_list_attrs = {'index', 'count'}
        safe_str_attrs = {'lower', 'upper', 'strip', 'split', 'join', 'replace', 'startswith', 'endswith'}

        if isinstance(value, dict) and attr in safe_dict_attrs:
            return getattr(value, attr)
        elif isinstance(value, list) and attr in safe_list_attrs:
            return getattr(value, attr)
        elif isinstance(value, str) and attr in safe_str_attrs:
            return getattr(value, attr)

        raise ValueError(f"Attribute access not allowed: {attr}")

    def visit_Call(self, node):
        """Handle function calls (limited to safe methods)."""
        func = self.visit(node.func)

        # Only allow calling bound methods that were retrieved via visit_Attribute
        if not callable(func):
            raise ValueError("Cannot call non-callable")

        args = [self.visit(arg) for arg in node.args]
        kwargs = {kw.arg: self.visit(kw.value) for kw in node.keywords}

        return func(*args, **kwargs)

    def visit_IfExp(self, node):
        """Handle ternary expressions (a if condition else b)."""
        condition = self.visit(node.test)
        if condition:
            return self.visit(node.body)
        else:
            return self.visit(node.orelse)

    def generic_visit(self, node):
        """Reject any node types not explicitly handled."""
        raise ValueError(f"Unsupported expression type: {type(node).__name__}")


def transform_step_data(transform_map_expr: str, input_data: dict) -> dict:
    """
    Transforms input data using a provided expression string.

    Args:
        transform_map_expr: A string representing a Python dictionary literal
                           that defines how to map input fields to output fields.
        input_data: Dictionary containing the input data from a previous step.

    Returns:
        A new dictionary with transformed data according to the expression.

    Raises:
        ValueError: If the expression contains unsafe operations.
        TypeError: If the result is not a dictionary.
    """
    if not isinstance(input_data, dict):
        raise TypeError("input_data must be a dictionary")

    if not isinstance(transform_map_expr, str):
        raise TypeError("transform_map_expr must be a string")

    # Create evaluator with input_data available as a variable
    evaluator = SafeExpressionEvaluator({'input_data': input_data})

    # Evaluate the expression safely
    result = evaluator.evaluate(transform_map_expr)

    if not isinstance(result, dict):
        raise TypeError("Transform expression must evaluate to a dictionary")

    return result

