import ast
import operator


# Safe operators allowed in expressions
SAFE_OPERATORS = {
    ast.Add: operator.add,
    ast.Sub: operator.sub,
    ast.Mult: operator.mul,
    ast.Div: operator.truediv,
    ast.FloorDiv: operator.floordiv,
    ast.Mod: operator.mod,
    ast.Pow: operator.pow,
    ast.USub: operator.neg,
    ast.UAdd: operator.pos,
    ast.Eq: operator.eq,
    ast.NotEq: operator.ne,
    ast.Lt: operator.lt,
    ast.LtE: operator.le,
    ast.Gt: operator.gt,
    ast.GtE: operator.ge,
    ast.And: lambda a, b: a and b,
    ast.Or: lambda a, b: a or b,
    ast.Not: operator.not_,
    ast.In: lambda a, b: a in b,
    ast.NotIn: lambda a, b: a not in b,
}

# Safe built-in functions
SAFE_BUILTINS = {
    'len': len,
    'str': str,
    'int': int,
    'float': float,
    'bool': bool,
    'list': list,
    'dict': dict,
    'tuple': tuple,
    'abs': abs,
    'min': min,
    'max': max,
    'sum': sum,
    'round': round,
    'sorted': sorted,
    'reversed': lambda x: list(reversed(x)),
    'enumerate': lambda x: list(enumerate(x)),
    'zip': lambda *args: list(zip(*args)),
    'range': range,
    'True': True,
    'False': False,
    'None': None,
}


class SafeExpressionEvaluator:
    """Safely evaluates a restricted subset of Python expressions."""

    def __init__(self, variables: dict):
        self.variables = variables

    def evaluate(self, expr: str) -> any:
        """Parse and evaluate the expression safely."""
        try:
            tree = ast.parse(expr, mode='eval')
        except SyntaxError as e:
            raise ValueError(f"Invalid expression syntax: {e}")

        return self._eval_node(tree.body)

    def _eval_node(self, node: ast.AST) -> any:
        """Recursively evaluate an AST node."""
        if isinstance(node, ast.Constant):
            return node.value

        # For Python 3.7 compatibility
        elif isinstance(node, ast.Num):
            return node.n
        elif isinstance(node, ast.Str):
            return node.s
        elif isinstance(node, ast.NameConstant):
            return node.value

        elif isinstance(node, ast.Dict):
            keys = [self._eval_node(k) if k is not None else None for k in node.keys]
            values = [self._eval_node(v) for v in node.values]
            return dict(zip(keys, values))

        elif isinstance(node, ast.List):
            return [self._eval_node(elem) for elem in node.elts]

        elif isinstance(node, ast.Tuple):
            return tuple(self._eval_node(elem) for elem in node.elts)

        elif isinstance(node, ast.Set):
            return {self._eval_node(elem) for elem in node.elts}

        elif isinstance(node, ast.Name):
            name = node.id
            if name in self.variables:
                return self.variables[name]
            elif name in SAFE_BUILTINS:
                return SAFE_BUILTINS[name]
            else:
                raise ValueError(f"Undefined variable: {name}")

        elif isinstance(node, ast.BinOp):
            left = self._eval_node(node.left)
            right = self._eval_node(node.right)
            op_type = type(node.op)
            if op_type not in SAFE_OPERATORS:
                raise ValueError(f"Unsupported operator: {op_type.__name__}")
            return SAFE_OPERATORS[op_type](left, right)

        elif isinstance(node, ast.UnaryOp):
            operand = self._eval_node(node.operand)
            op_type = type(node.op)
            if op_type not in SAFE_OPERATORS:
                raise ValueError(f"Unsupported unary operator: {op_type.__name__}")
            return SAFE_OPERATORS[op_type](operand)

        elif isinstance(node, ast.Compare):
            left = self._eval_node(node.left)
            for op, comparator in zip(node.ops, node.comparators):
                right = self._eval_node(comparator)
                op_type = type(op)
                if op_type not in SAFE_OPERATORS:
                    raise ValueError(f"Unsupported comparison operator: {op_type.__name__}")
                if not SAFE_OPERATORS[op_type](left, right):
                    return False
                left = right
            return True

        elif isinstance(node, ast.BoolOp):
            op_type = type(node.op)
            if op_type not in SAFE_OPERATORS:
                raise ValueError(f"Unsupported boolean operator: {op_type.__name__}")

            if isinstance(node.op, ast.And):
                result = True
                for value in node.values:
                    result = self._eval_node(value)
                    if not result:
                        return result
                return result
            else:  # Or
                result = False
                for value in node.values:
                    result = self._eval_node(value)
                    if result:
                        return result
                return result

        elif isinstance(node, ast.Subscript):
            value = self._eval_node(node.value)
            if isinstance(node.slice, ast.Index):
                # Python 3.8 and earlier
                index = self._eval_node(node.slice.value)
            else:
                # Python 3.9+
                index = self._eval_node(node.slice)
            return value[index]

        elif isinstance(node, ast.Attribute):
            value = self._eval_node(node.value)
            attr = node.attr
            # Only allow safe attribute access (no dunder methods)
            if attr.startswith('_'):
                raise ValueError(f"Access to private attributes is not allowed: {attr}")
            # Allow common dict/list methods
            safe_methods = {'get', 'keys', 'values', 'items', 'copy', 'upper', 'lower', 
                          'strip', 'split', 'join', 'replace', 'startswith', 'endswith',
                          'append', 'extend', 'pop', 'index', 'count'}
            if hasattr(value, attr):
                result = getattr(value, attr)
                if callable(result) and attr not in safe_methods:
                    raise ValueError(f"Method call not allowed: {attr}")
                return result
            raise ValueError(f"Attribute not found: {attr}")

        elif isinstance(node, ast.Call):
            func = self._eval_node(node.func)
            if not callable(func):
                raise ValueError("Attempted to call non-callable")

            # Check if it's a safe function
            args = [self._eval_node(arg) for arg in node.args]
            kwargs = {kw.arg: self._eval_node(kw.value) for kw in node.keywords}

            return func(*args, **kwargs)

        elif isinstance(node, ast.IfExp):
            test = self._eval_node(node.test)
            if test:
                return self._eval_node(node.body)
            else:
                return self._eval_node(node.orelse)

        elif isinstance(node, ast.ListComp):
            return self._eval_comprehension(node, list)

        elif isinstance(node, ast.DictComp):
            return self._eval_dict_comprehension(node)

        elif isinstance(node, ast.Slice):
            lower = self._eval_node(node.lower) if node.lower else None
            upper = self._eval_node(node.upper) if node.upper else None
            step = self._eval_node(node.step) if node.step else None
            return slice(lower, upper, step)

        else:
            raise ValueError(f"Unsupported expression type: {type(node).__name__}")

    def _eval_comprehension(self, node: ast.ListComp, container_type):
        """Evaluate list comprehension safely."""
        result = []
        self._eval_generators(node.generators, 0, node.elt, result)
        return container_type(result)

    def _eval_generators(self, generators, index, elt, result):
        """Recursively evaluate comprehension generators."""
        if index >= len(generators):
            result.append(self._eval_node(elt))
            return

        gen = generators[index]
        if not isinstance(gen.target, ast.Name):
            raise ValueError("Only simple variable names allowed in comprehensions")

        var_name = gen.target.id
        iterable = self._eval_node(gen.iter)

        for item in iterable:
            old_value = self.variables.get(var_name)
            self.variables[var_name] = item

            # Check all conditions
            if all(self._eval_node(if_clause) for if_clause in gen.ifs):
                self._eval_generators(generators, index + 1, elt, result)

            # Restore old value
            if old_value is not None:
                self.variables[var_name] = old_value
            elif var_name in self.variables:
                del self.variables[var_name]

    def _eval_dict_comprehension(self, node: ast.DictComp):
        """Evaluate dict comprehension safely."""
        result = {}
        self._eval_dict_generators(node.generators, 0, node.key, node.value, result)
        return result

    def _eval_dict_generators(self, generators, index, key_node, value_node, result):
        """Recursively evaluate dict comprehension generators."""
        if index >= len(generators):
            key = self._eval_node(key_node)
            value = self._eval_node(value_node)
            result[key] = value
            return

        gen = generators[index]
        if not isinstance(gen.target, ast.Name):
            raise ValueError("Only simple variable names allowed in comprehensions")

        var_name = gen.target.id
        iterable = self._eval_node(gen.iter)

        for item in iterable:
            old_value = self.variables.get(var_name)
            self.variables[var_name] = item

            if all(self._eval_node(if_clause) for if_clause in gen.ifs):
                self._eval_dict_generators(generators, index + 1, key_node, value_node, result)

            if old_value is not None:
                self.variables[var_name] = old_value
            elif var_name in self.variables:
                del self.variables[var_name]


def transform_step_data(transform_map_expr: str, input_data: dict) -> dict:
    """
    Transforms input data using a provided expression string.

    Args:
        transform_map_expr: A string representing a Python dictionary literal
                           that defines how to map input fields to output fields.
        input_data: Dictionary containing the input data from a previous step.

    Returns:
        A new dictionary with transformed data according to the expression.

    Raises:
        ValueError: If the expression contains unsafe operations or syntax errors.
        TypeError: If the result is not a dictionary.
    """
    if not isinstance(input_data, dict):
        raise TypeError("input_data must be a dictionary")

    if not isinstance(transform_map_expr, str):
        raise TypeError("transform_map_expr must be a string")

    # Create evaluator with input_data available as a variable
    evaluator = SafeExpressionEvaluator({'input_data': input_data})

    # Safely evaluate the expression
    result = evaluator.evaluate(transform_map_expr)

    if not isinstance(result, dict):
        raise TypeError(f"Expression must evaluate to a dictionary, got {type(result).__name__}")

    return result

