class SafeEvaluator(ast.NodeVisitor):
    """Safely evaluates a restricted subset of Python expressions."""

    def __init__(self, variables: Dict[str, Any]):
        self.variables = variables

    def visit(self, node: ast.AST) -> Any:
        return super().visit(node)

    def generic_visit(self, node: ast.AST) -> Any:
        raise ValueError(f"Unsupported expression type: {type(node).__name__}")

    def visit_Expression(self, node: ast.Expression) -> Any:
        return self.visit(node.body)

    def visit_Constant(self, node: ast.Constant) -> Any:
        return node.value

    def visit_Num(self, node: ast.Num) -> Any:
        return node.n

    def visit_Str(self, node: ast.Str) -> Any:
        return node.s

    def visit_NameConstant(self, node: ast.NameConstant) -> Any:
        return node.value

    def visit_Name(self, node: ast.Name) -> Any:
        name = node.id
        if name in self.variables:
            return self.variables[name]
        if name in SAFE_BUILTINS:
            return SAFE_BUILTINS[name]
        raise ValueError(f"Undefined variable: {name}")

    def visit_Dict(self, node: ast.Dict) -> Dict:
        keys = [self.visit(k) if k is not None else None for k in node.keys]
        values = [self.visit(v) for v in node.values]
        result = {}
        for k, v in zip(keys, values):
            if k is None:
                # Handle dictionary unpacking **expr
                if isinstance(v, dict):
                    result.update(v)
                else:
                    raise ValueError("Dictionary unpacking requires a dict")
            else:
                result[k] = v
        return result

    def visit_List(self, node: ast.List) -> list:
        return [self.visit(elem) for elem in node.elts]

    def visit_Tuple(self, node: ast.Tuple) -> tuple:
        return tuple(self.visit(elem) for elem in node.elts)

    def visit_Set(self, node: ast.Set) -> set:
        return {self.visit(elem) for elem in node.elts}

    def visit_BinOp(self, node: ast.BinOp) -> Any:
        op_type = type(node.op)
        if op_type not in SAFE_BINARY_OPS:
            raise ValueError(f"Unsupported binary operator: {op_type.__name__}")
        left = self.visit(node.left)
        right = self.visit(node.right)
        return SAFE_BINARY_OPS[op_type](left, right)

    def visit_UnaryOp(self, node: ast.UnaryOp) -> Any:
        op_type = type(node.op)
        if op_type not in SAFE_UNARY_OPS:
            raise ValueError(f"Unsupported unary operator: {op_type.__name__}")
        operand = self.visit(node.operand)
        return SAFE_UNARY_OPS[op_type](operand)

    def visit_Compare(self, node: ast.Compare) -> bool:
        left = self.visit(node.left)
        for op, comparator in zip(node.ops, node.comparators):
            op_type = type(op)
            if op_type not in SAFE_COMPARE_OPS:
                raise ValueError(f"Unsupported comparison operator: {op_type.__name__}")
            right = self.visit(comparator)
            if not SAFE_COMPARE_OPS[op_type](left, right):
                return False
            left = right
        return True

    def visit_BoolOp(self, node: ast.BoolOp) -> bool:
        if isinstance(node.op, ast.And):
            for value in node.values:
                if not self.visit(value):
                    return False
            return True
        elif isinstance(node.op, ast.Or):
            for value in node.values:
                if self.visit(value):
                    return True
            return False
        raise ValueError(f"Unsupported boolean operator: {type(node.op).__name__}")

    def visit_IfExp(self, node: ast.IfExp) -> Any:
        if self.visit(node.test):
            return self.visit(node.body)
        return self.visit(node.orelse)

    def visit_Subscript(self, node: ast.Subscript) -> Any:
        value = self.visit(node.value)
        slice_val = self.visit(node.slice)
        return value[slice_val]

    def visit_Index(self, node: ast.Index) -> Any:
        return self.visit(node.value)

    def visit_Slice(self, node: ast.Slice) -> slice:
        lower = self.visit(node.lower) if node.lower else None
        upper = self.visit(node.upper) if node.upper else None
        step = self.visit(node.step) if node.step else None
        return slice(lower, upper, step)

    def visit_Attribute(self, node: ast.Attribute) -> Any:
        value = self.visit(node.value)
        attr = node.attr
        # Only allow safe attribute access (no dunder methods)
        if attr.startswith('_'):
            raise ValueError(f"Access to private attributes is not allowed: {attr}")
        if not hasattr(value, attr):
            raise ValueError(f"Attribute '{attr}' not found")
        return getattr(value, attr)

    def visit_Call(self, node: ast.Call) -> Any:
        func = self.visit(node.func)
        # Check if the function is in our safe builtins
        if func not in SAFE_BUILTINS.values():
            # Also allow safe dict/list/str methods
            if not callable(func):
                raise ValueError("Attempted to call a non-callable")
            # Check if it's a method of a safe type
            func_name = getattr(func, '__name__', '')
            if func_name.startswith('_'):
                raise ValueError(f"Calling private methods is not allowed: {func_name}")

        args = [self.visit(arg) for arg in node.args]
        kwargs = {kw.arg: self.visit(kw.value) for kw in node.keywords if kw.arg}
        return func(*args, **kwargs)

    def visit_ListComp(self, node: ast.ListComp) -> list:
        return self._eval_comprehension(node, list)

    def visit_DictComp(self, node: ast.DictComp) -> dict:
        return self._eval_dict_comprehension(node)

    def _eval_comprehension(self, node: ast.ListComp, result_type: type) -> Any:
        if len(node.generators) != 1:
            raise ValueError("Only single-loop comprehensions are supported")

        gen = node.generators[0]
        if gen.is_async:
            raise ValueError("Async comprehensions are not supported")

        iterable = self.visit(gen.iter)
        result = []

        for item in iterable:
            # Create new scope with loop variable
            old_vars = self.variables.copy()
            self._assign_target(gen.target, item)

            # Check conditions
            if all(self.visit(if_clause) for if_clause in gen.ifs):
                result.append(self.visit(node.elt))

            self.variables = old_vars

        return result

    def _eval_dict_comprehension(self, node: ast.DictComp) -> dict:
        if len(node.generators) != 1:
            raise ValueError("Only single-loop comprehensions are supported")

        gen = node.generators[0]
        if gen.is_async:
            raise ValueError("Async comprehensions are not supported")

        iterable = self.visit(gen.iter)
        result = {}

        for item in iterable:
            old_vars = self.variables.copy()
            self._assign_target(gen.target, item)

            if all(self.visit(if_clause) for if_clause in gen.ifs):
                key = self.visit(node.key)
                value = self.visit(node.value)
                result[key] = value

            self.variables = old_vars

        return result

    def _assign_target(self, target: ast.AST, value: Any) -> None:
        if isinstance(target, ast.Name):
            self.variables[target.id] = value
        elif isinstance(target, ast.Tuple):
            for t, v in zip(target.elts, value):
                self._assign_target(t, v)
        else:
            raise ValueError(f"Unsupported assignment target: {type(target).__name__}")


def transform_step_data(transform_map_expr: str, input_data: dict) -> dict:
    """
    Transforms input data using a provided expression string.

    Args:
        transform_map_expr: A string representing a Python dictionary literal
                           that defines how to map input fields to output fields.
        input_data: Dictionary containing the input data from a previous step.

    Returns:
        A new dictionary with transformed data according to the expression.

    Raises:
        ValueError: If the expression contains unsupported or unsafe operations.
        SyntaxError: If the expression is not valid Python syntax.
    """
    if not isinstance(transform_map_expr, str):
        raise TypeError("transform_map_expr must be a string")

    if not isinstance(input_data, dict):
        raise TypeError("input_data must be a dictionary")

    # Parse the expression into an AST
    try:
        tree = ast.parse(transform_map_expr, mode='eval')
    except SyntaxError as e:
        raise SyntaxError(f"Invalid expression syntax: {e}")

    # Create evaluator with input_data available as a variable
    variables = {'input_data': input_data}
    evaluator = SafeEvaluator(variables)

    # Safely evaluate the expression
    result = evaluator.visit(tree)

    if not isinstance(result, dict):
        raise ValueError("Transform expression must evaluate to a dictionary")

    return result

"""
Workflow data transformation module for processing step outputs.
"""

import ast
import operator
from typing import Any, Dict


class SafeExpressionEvaluator(ast.NodeVisitor):
    """
    A safe expression evaluator that only allows whitelisted operations.
    """

    # Allowed binary operators
    BINARY_OPS = {
        ast.Add: operator.add,
        ast.Sub: operator.sub,
        ast.Mult: operator.mul,
        ast.Div: operator.truediv,
        ast.FloorDiv: operator.floordiv,
        ast.Mod: operator.mod,
        ast.Pow: operator.pow,
        ast.BitOr: operator.or_,
        ast.BitXor: operator.xor,
        ast.BitAnd: operator.and_,
    }

    # Allowed comparison operators
    COMPARE_OPS = {
        ast.Eq: operator.eq,
        ast.NotEq: operator.ne,
        ast.Lt: operator.lt,
        ast.LtE: operator.le,
        ast.Gt: operator.gt,
        ast.GtE: operator.ge,
        ast.In: lambda a, b: a in b,
        ast.NotIn: lambda a, b: a not in b,
        ast.Is: operator.is_,
        ast.IsNot: operator.is_not,
    }

    # Allowed unary operators
    UNARY_OPS = {
        ast.UAdd: operator.pos,
        ast.USub: operator.neg,
        ast.Not: operator.not_,
        ast.Invert: operator.invert,
    }

    # Allowed safe built-in functions
    SAFE_FUNCTIONS = {
        'len': len,
        'str': str,
        'int': int,
        'float': float,
        'bool': bool,
        'list': list,
        'dict': dict,
        'tuple': tuple,
        'abs': abs,
        'min': min,
        'max': max,
        'sum': sum,
        'round': round,
        'sorted': sorted,
        'reversed': lambda x: list(reversed(x)),
        'enumerate': lambda x: list(enumerate(x)),
        'zip': lambda *args: list(zip(*args)),
        'range': lambda *args: list(range(*args)),
        'all': all,
        'any': any,
    }

    # Safe string methods
    SAFE_STR_METHODS = {
        'lower', 'upper', 'strip', 'lstrip', 'rstrip', 'split', 'join',
        'replace', 'startswith', 'endswith', 'find', 'rfind', 'index',
        'count', 'isdigit', 'isalpha', 'isalnum', 'title', 'capitalize',
        'format',
    }

    # Safe dict methods
    SAFE_DICT_METHODS = {
        'get', 'keys', 'values', 'items', 'copy',
    }

    # Safe list methods
    SAFE_LIST_METHODS = {
        'copy', 'count', 'index',
    }

    def __init__(self, variables: Dict[str, Any]):
        self.variables = variables

    def evaluate(self, expr: str) -> Any:
        """Parse and evaluate the expression safely."""
        try:
            tree = ast.parse(expr, mode='eval')
        except SyntaxError as e:
            raise ValueError(f"Invalid expression syntax: {e}")

        return self.visit(tree.body)

    def visit(self, node: ast.AST) -> Any:
        method_name = f'visit_{node.__class__.__name__}'
        visitor = getattr(self, method_name, None)
        if visitor is None:
            raise ValueError(f"Unsupported expression element: {node.__class__.__name__}")
        return visitor(node)

    def visit_Constant(self, node: ast.Constant) -> Any:
        """Handle literal constants (strings, numbers, None, True, False)."""
        return node.value

    def visit_Num(self, node: ast.Num) -> Any:
        """Handle numeric literals (Python 3.7 compatibility)."""
        return node.n

    def visit_Str(self, node: ast.Str) -> Any:
        """Handle string literals (Python 3.7 compatibility)."""
        return node.s

    def visit_NameConstant(self, node: ast.NameConstant) -> Any:
        """Handle True, False, None (Python 3.7 compatibility)."""
        return node.value

    def visit_Name(self, node: ast.Name) -> Any:
        """Handle variable references - only allow whitelisted variables."""
        name = node.id
        if name in self.variables:
            return self.variables[name]
        if name in self.SAFE_FUNCTIONS:
            return self.SAFE_FUNCTIONS[name]
        if name in ('True', 'False', 'None'):
            return {'True': True, 'False': False, 'None': None}[name]
        raise ValueError(f"Access to variable '{name}' is not allowed")

    def visit_Dict(self, node: ast.Dict) -> dict:
        """Handle dictionary literals."""
        keys = [self.visit(k) if k is not None else None for k in node.keys]
        values = [self.visit(v) for v in node.values]

        result = {}
        for k, v in zip(keys, values):
            if k is None:
                # Handle dictionary unpacking (**)
                if isinstance(v, dict):
                    result.update(v)
                else:
                    raise ValueError("Dictionary unpacking requires a dict")
            else:
                result[k] = v
        return result

    def visit_List(self, node: ast.List) -> list:
        """Handle list literals."""
        return [self.visit(elem) for elem in node.elts]

    def visit_Tuple(self, node: ast.Tuple) -> tuple:
        """Handle tuple literals."""
        return tuple(self.visit(elem) for elem in node.elts)

    def visit_Set(self, node: ast.Set) -> set:
        """Handle set literals."""
        return {self.visit(elem) for elem in node.elts}

    def visit_BinOp(self, node: ast.BinOp) -> Any:
        """Handle binary operations."""
        op_type = type(node.op)
        if op_type not in self.BINARY_OPS:
            raise ValueError(f"Unsupported binary operator: {op_type.__name__}")

        left = self.visit(node.left)
        right = self.visit(node.right)
        return self.BINARY_OPS[op_type](left, right)

    def visit_UnaryOp(self, node: ast.UnaryOp) -> Any:
        """Handle unary operations."""
        op_type = type(node.op)
        if op_type not in self.UNARY_OPS:
            raise ValueError(f"Unsupported unary operator: {op_type.__name__}")

        operand = self.visit(node.operand)
        return self.UNARY_OPS[op_type](operand)

    def visit_Compare(self, node: ast.Compare) -> bool:
        """Handle comparison operations."""
        left = self.visit(node.left)

        for op, comparator in zip(node.ops, node.comparators):
            op_type = type(op)
            if op_type not in self.COMPARE_OPS:
                raise ValueError(f"Unsupported comparison operator: {op_type.__name__}")

            right = self.visit(comparator)
            if not self.COMPARE_OPS[op_type](left, right):
                return False
            left = right

        return True

    def visit_BoolOp(self, node: ast.BoolOp) -> bool:
        """Handle boolean operations (and, or)."""
        if isinstance(node.op, ast.And):
            for value in node.values:
                result = self.visit(value)
                if not result:
                    return result
            return result
        elif isinstance(node.op, ast.Or):
            for value in node.values:
                result = self.visit(value)
                if result:
                    return result
            return result
        else:
            raise ValueError(f"Unsupported boolean operator: {type(node.op).__name__}")

    def visit_IfExp(self, node: ast.IfExp) -> Any:
        """Handle ternary if expressions (a if condition else b)."""
        if self.visit(node.test):
            return self.visit(node.body)
        else:
            return self.visit(node.orelse)

    def visit_Subscript(self, node: ast.Subscript) -> Any:
        """Handle subscript operations (obj[key])."""
        value = self.visit(node.value)

        # Handle slice vs index
        if isinstance(node.slice, ast.Slice):
            lower = self.visit(node.slice.lower) if node.slice.lower else None
            upper = self.visit(node.slice.upper) if node.slice.upper else None
            step = self.visit(node.slice.step) if node.slice.step else None
            return value[lower:upper:step]
        else:
            # Python 3.9+ uses the slice directly, older versions wrap in Index
            if hasattr(ast, 'Index') and isinstance(node.slice, ast.Index):
                key = self.visit(node.slice.value)
            else:
                key = self.visit(node.slice)
            return value[key]

    def visit_Attribute(self, node: ast.Attribute) -> Any:
        """Handle attribute access - only allow safe methods."""
        value = self.visit(node.value)
        attr = node.attr

        # Check if this is a safe method access
        if isinstance(value, str) and attr in self.SAFE_STR_METHODS:
            return getattr(value, attr)
        elif isinstance(value, dict) and attr in self.SAFE_DICT_METHODS:
            return getattr(value, attr)
        elif isinstance(value, (list, tuple)) and attr in self.SAFE_LIST_METHODS:
            return getattr(value, attr)
        else:
            raise ValueError(f"Access to attribute '{attr}' is not allowed")

    def visit_Call(self, node: ast.Call) -> Any:
        """Handle function calls - only allow safe functions."""
        func = self.visit(node.func)

        # Verify it's a safe callable
        safe_callables = set(self.SAFE_FUNCTIONS.values())

        # Also allow bound methods from safe method sets
        is_safe_method = False
        if hasattr(func, '__self__'):
            obj = func.__self__
            method_name = func.__name__
            if isinstance(obj, str) and method_name in self.SAFE_STR_METHODS:
                is_safe_method = True
            elif isinstance(obj, dict) and method_name in self.SAFE_DICT_METHODS:
                is_safe_method = True
            elif isinstance(obj, (list, tuple)) and method_name in self.SAFE_LIST_METHODS:
                is_safe_method = True

        if func not in safe_callables and not is_safe_method:
            raise ValueError("Calling this function is not allowed")

        args = [self.visit(arg) for arg in node.args]
        kwargs = {kw.arg: self.visit(kw.value) for kw in node.keywords if kw.arg}

        return func(*args, **kwargs)

    def visit_ListComp(self, node: ast.ListComp) -> list:
        """Handle list comprehensions."""
        return self._handle_comprehension(node, list)

    def visit_DictComp(self, node: ast.DictComp) -> dict:
        """Handle dictionary comprehensions."""
        return self._handle_dict_comprehension(node)

    def _handle_comprehension(self, node, container_type):
        """Helper for list/set comprehensions."""
        if len(node.generators) != 1:
            raise ValueError("Only single-loop comprehensions are supported")

        gen = node.generators[0]
        if gen.is_async:
            raise ValueError("Async comprehensions are not supported")

        iterable = self.visit(gen.iter)
        target_name = gen.target.id if isinstance(gen.target, ast.Name) else None

        if target_name is None:
            raise ValueError("Complex comprehension targets are not supported")

        result = []
        for item in iterable:
            # Create new scope with loop variable
            old_vars = self.variables.copy()
            self.variables[target_name] = item

            # Check all conditions
            include = True
            for if_clause in gen.ifs:
                if not self.visit(if_clause):
                    include = False
                    break

            if include:
                result.append(self.visit(node.elt))

            self.variables = old_vars

        return container_type(result)

    def _handle_dict_comprehension(self, node):
        """Helper for dict comprehensions."""
        if len(node.generators) != 1:
            raise ValueError("Only single-loop comprehensions are supported")

        gen = node.generators[0]
        if gen.is_async:
            raise ValueError("Async comprehensions are not supported")

        iterable = self.visit(gen.iter)
        target_name = gen.target.id if isinstance(gen.target, ast.Name) else None

        if target_name is None:
            raise ValueError("Complex comprehension targets are not supported")

        result = {}
        for item in iterable:
            old_vars = self.variables.copy()
            self.variables[target_name] = item

            include = True
            for if_clause in gen.ifs:
                if not self.visit(if_clause):
                    include = False
                    break

            if include:
                key = self.visit(node.key)
                value = self.visit(node.value)
                result[key] = value

            self.variables = old_vars

        return result


def transform_step_data(transform_map_expr: str, input_data: dict) -> dict:
    """
    Transforms input data using a provided expression string.

    Args:
        transform_map_expr: A string representing a Python expression
                           that defines how to map input fields to output fields.
                           The input data is available as 'input_data'.
        input_data: Dictionary containing the input data from a previous step.

    Returns:
        A new dictionary with transformed data according to the expression.
    """
    evaluator = SafeExpressionEvaluator({'input_data': input_data})
    result = evaluator.evaluate(transform_map_expr)

    if not isinstance(result, dict):
        raise ValueError("Transform expression must evaluate to a dictionary")

    return result

"""
Workflow data transformation module for processing step outputs.
"""
import ast
import operator


# Safe operators for arithmetic, comparison, and logical operations
SAFE_OPERATORS = {
    ast.Add: operator.add,
    ast.Sub: operator.sub,
    ast.Mult: operator.mul,
    ast.Div: operator.truediv,
    ast.FloorDiv: operator.floordiv,
    ast.Mod: operator.mod,
    ast.Pow: operator.pow,
    ast.USub: operator.neg,
    ast.UAdd: operator.pos,
    ast.Eq: operator.eq,
    ast.NotEq: operator.ne,
    ast.Lt: operator.lt,
    ast.LtE: operator.le,
    ast.Gt: operator.gt,
    ast.GtE: operator.ge,
    ast.And: lambda a, b: a and b,
    ast.Or: lambda a, b: a or b,
    ast.Not: operator.not_,
    ast.In: lambda a, b: a in b,
    ast.NotIn: lambda a, b: a not in b,
}

# Safe built-in functions
SAFE_BUILTINS = {
    'len': len,
    'str': str,
    'int': int,
    'float': float,
    'bool': bool,
    'list': list,
    'dict': dict,
    'tuple': tuple,
    'abs': abs,
    'min': min,
    'max': max,
    'sum': sum,
    'round': round,
    'sorted': sorted,
    'reversed': reversed,
    'enumerate': enumerate,
    'zip': zip,
    'range': range,
    'True': True,
    'False': False,
    'None': None,
}


class SafeEvaluator(ast.NodeVisitor):
    """
    A safe expression evaluator that only allows whitelisted operations.
    """

    def __init__(self, variables: dict):
        self.variables = variables

    def evaluate(self, expr: str):
        """Parse and safely evaluate an expression."""
        try:
            tree = ast.parse(expr, mode='eval')
        except SyntaxError as e:
            raise ValueError(f"Invalid expression syntax: {e}")

        return self.visit(tree.body)

    def visit(self, node):
        """Visit a node and evaluate it."""
        method_name = f'visit_{node.__class__.__name__}'
        visitor = getattr(self, method_name, None)
        if visitor is None:
            raise ValueError(f"Unsupported operation: {node.__class__.__name__}")
        return visitor(node)

    def visit_Constant(self, node):
        """Handle constant values (strings, numbers, etc.)."""
        return node.value

    def visit_Num(self, node):
        """Handle numeric literals (Python 3.7 compatibility)."""
        return node.n

    def visit_Str(self, node):
        """Handle string literals (Python 3.7 compatibility)."""
        return node.s

    def visit_NameConstant(self, node):
        """Handle True, False, None (Python 3.7 compatibility)."""
        return node.value

    def visit_Name(self, node):
        """Handle variable references."""
        name = node.id
        if name in self.variables:
            return self.variables[name]
        if name in SAFE_BUILTINS:
            return SAFE_BUILTINS[name]
        raise ValueError(f"Unknown variable: {name}")

    def visit_Dict(self, node):
        """Handle dictionary literals."""
        keys = [self.visit(k) for k in node.keys]
        values = [self.visit(v) for v in node.values]
        return dict(zip(keys, values))

    def visit_List(self, node):
        """Handle list literals."""
        return [self.visit(el) for el in node.elts]

    def visit_Tuple(self, node):
        """Handle tuple literals."""
        return tuple(self.visit(el) for el in node.elts)

    def visit_Set(self, node):
        """Handle set literals."""
        return {self.visit(el) for el in node.elts}

    def visit_BinOp(self, node):
        """Handle binary operations."""
        op_type = type(node.op)
        if op_type not in SAFE_OPERATORS:
            raise ValueError(f"Unsupported binary operator: {op_type.__name__}")
        left = self.visit(node.left)
        right = self.visit(node.right)
        return SAFE_OPERATORS[op_type](left, right)

    def visit_UnaryOp(self, node):
        """Handle unary operations."""
        op_type = type(node.op)
        if op_type not in SAFE_OPERATORS:
            raise ValueError(f"Unsupported unary operator: {op_type.__name__}")
        operand = self.visit(node.operand)
        return SAFE_OPERATORS[op_type](operand)

    def visit_Compare(self, node):
        """Handle comparison operations."""
        left = self.visit(node.left)
        for op, comparator in zip(node.ops, node.comparators):
            op_type = type(op)
            if op_type not in SAFE_OPERATORS:
                raise ValueError(f"Unsupported comparison operator: {op_type.__name__}")
            right = self.visit(comparator)
            if not SAFE_OPERATORS[op_type](left, right):
                return False
            left = right
        return True

    def visit_BoolOp(self, node):
        """Handle boolean operations (and, or)."""
        op_type = type(node.op)
        if op_type == ast.And:
            result = True
            for value in node.values:
                result = self.visit(value)
                if not result:
                    return result
            return result
        elif op_type == ast.Or:
            result = False
            for value in node.values:
                result = self.visit(value)
                if result:
                    return result
            return result
        raise ValueError(f"Unsupported boolean operator: {op_type.__name__}")

    def visit_IfExp(self, node):
        """Handle ternary if expressions."""
        if self.visit(node.test):
            return self.visit(node.body)
        return self.visit(node.orelse)

    def visit_Subscript(self, node):
        """Handle subscript operations (e.g., input_data['key'])."""
        value = self.visit(node.value)
        if isinstance(node.slice, ast.Index):
            # Python 3.8 and earlier
            index = self.visit(node.slice.value)
        else:
            # Python 3.9+
            index = self.visit(node.slice)
        return value[index]

    def visit_Index(self, node):
        """Handle index nodes (Python 3.8 compatibility)."""
        return self.visit(node.value)

    def visit_Slice(self, node):
        """Handle slice operations."""
        lower = self.visit(node.lower) if node.lower else None
        upper = self.visit(node.upper) if node.upper else None
        step = self.visit(node.step) if node.step else None
        return slice(lower, upper, step)

    def visit_Call(self, node):
        """Handle function calls (only safe built-ins)."""
        func = self.visit(node.func)

        # Only allow safe built-in functions
        if func not in SAFE_BUILTINS.values():
            raise ValueError("Only safe built-in functions are allowed")

        args = [self.visit(arg) for arg in node.args]
        kwargs = {kw.arg: self.visit(kw.value) for kw in node.keywords}

        return func(*args, **kwargs)

    def visit_ListComp(self, node):
        """Handle list comprehensions."""
        return self._eval_comprehension(node, list)

    def visit_DictComp(self, node):
        """Handle dict comprehensions."""
        result = {}
        for scope in self._iter_comprehension(node.generators):
            key = self.visit(node.key)
            value = self.visit(node.value)
            result[key] = value
        return result

    def _eval_comprehension(self, node, container_type):
        """Evaluate a comprehension expression."""
        results = []
        for scope in self._iter_comprehension(node.generators):
            results.append(self.visit(node.elt))
        return container_type(results)

    def _iter_comprehension(self, generators):
        """Iterate through comprehension generators."""
        if not generators:
            yield
            return

        gen = generators[0]
        iter_val = self.visit(gen.iter)

        for item in iter_val:
            # Temporarily add the loop variable
            if isinstance(gen.target, ast.Name):
                old_val = self.variables.get(gen.target.id)
                self.variables[gen.target.id] = item

            # Check conditions
            if all(self.visit(if_clause) for if_clause in gen.ifs):
                yield from self._iter_comprehension(generators[1:])

            # Restore old value
            if isinstance(gen.target, ast.Name):
                if old_val is None:
                    self.variables.pop(gen.target.id, None)
                else:
                    self.variables[gen.target.id] = old_val


def transform_step_data(transform_map_expr: str, input_data: dict) -> dict:
    """
    Transforms input data using a provided expression string.

    Args:
        transform_map_expr: A string representing a Python dictionary literal
                           that defines how to map input fields to output fields.
        input_data: Dictionary containing the input data from a previous step.

    Returns:
        A new dictionary with transformed data according to the expression.

    Raises:
        ValueError: If the expression contains unsafe operations or invalid syntax.
        TypeError: If the result is not a dictionary.
    """
    if not isinstance(input_data, dict):
        raise TypeError("input_data must be a dictionary")

    if not isinstance(transform_map_expr, str):
        raise TypeError("transform_map_expr must be a string")

    # Create safe evaluator with input_data as the only allowed variable
    variables = {'input_data': input_data}
    evaluator = SafeEvaluator(variables)

    # Safely evaluate the expression
    result = evaluator.evaluate(transform_map_expr)

    if not isinstance(result, dict):
        raise TypeError("Transform expression must evaluate to a dictionary")

    return result
